SELECT 
  UPPER(
    TRIM(
      SUBSTRING_INDEX(
        SUBSTRING_INDEX(
          REPLACE(CONCAT(' ', ALIAS, ' '), '  ', ' '),
          ' BINTI ',
          -1
        ),
        ' BIN ',
        -1
      )
    )
  ) AS data
FROM (
  SELECT 
    UPPER(
      TRIM(
        SUBSTRING_INDEX(
          SUBSTRING_INDEX(
            REPLACE(CONCAT(' ', UPPER("#1033#"), ' '), '  ', ' '),
            ' ALIAS ',
            1
          ),
          ' BIN ',
          -1
        )
      )
    ) AS ALIAS
) AS temp;

