Bahwa perkara <i>a quo</i> oleh #7036# melalui kuasanya didaftarkan secara <i>e-Court</i> sehingga terdaftar sebagai pihak #7082#, sedangkan #7037# juga didampingi/wakili kuasanya yang terdaftar sebagai pihak #7138#, maka berdasarkan ketentuan Surat Keputusan Ketua Mahkamah Agung Nomor 363/KMA/SK/XII/2022 tentang Petunjuk Teknis Administrasi Dan Persidangan Perkara Perdata, Perdata Agama, Dan Tata Usaha Negara Di Pengadilan Secara Elektronik Ketua Mahkamah Agung Republik Indonesia, baik disetujui beracara secara elektronik ataupun tidak dari #7037#, perkara akan tetap diperiksa dan disidangkan secara <i>e-Litigasi</i>;"
        )
    WHEN EXISTS (
        SELECT 1
        FROM perkara
        LEFT JOIN perkara_efiling_id ON perkara.perkara_id = perkara_efiling_id.perkara_id
        WHERE perkara.perkara_id = '#perkara_id#' 
            AND perkara_efiling_id.efiling_id != '' 
            AND '#0106#' = ''
            AND '#0170#' != ''
    ) AND sidang.dihadiri_oleh = 1 AND alur_perkara_id = 15 THEN
        CONCAT(
            "<br>Bahwa, #7036# mengajukan #0053# <i>a quo</i> secara elektronik melalui aplikasi <i>e-Court</i>;
Bahwa, #7036# menyerahkan asli surat #0053#, kemudian #0690# memeriksa identitas #7036# yang ternyata sesuai dengan yang tertera dalam surat #0053#;
Bahwa, #0690# memeriksa identitas kuasa dari #7037# serta telah memeriksa kelengkapan dan keabsahan dokumen para kuasa sebagai penerima kuasa advokat/pengacara meliputi surat kuasa, Berita Acara Sumpah sebagai advokat/pengacara dan Kartu Tanda Pengenal Advokat (KTPA) dari kuasa #7037#, yaitu bernama #0170#, adalah Advokat pada kantor hukum #0157#, yang beralamat di #0173#, dengan berdomisili elektronik pada alamat #0137#, berdasarkan surat kuasa khusus tanggal #0185#, dan telah terdaftar pada Kepaniteraan nomor #0198# tanggal #0112#. Oleh karena itu, #0690# menyatakan kuasa tersebut dapat diterima kedudukannya secara sah sebagai kuasa #7037#;
#7140#
Bahwa perkara <i>a quo</i> oleh #7036# didaftarkan secara <i>e-Court</i> sehingga terdaftar sebagai pihak #7082#, sedangkan #7037# juga didampingi/wakili kuasanya yang terdaftar sebagai pihak #7138#, maka berdasarkan ketentuan Surat Keputusan Ketua Mahkamah Agung Nomor 363/KMA/SK/XII/2022 tentang Petunjuk Teknis Administrasi Dan Persidangan Perkara Perdata, Perdata Agama, Dan Tata Usaha Negara Di Pengadilan Secara Elektronik Ketua Mahkamah Agung Republik Indonesia, baik disetujui beracara secara elektronik ataupun tidak dari #7037#, perkara akan tetap diperiksa dan disidangkan secara <i>e-Litigasi</i>;"
        )
    WHEN (
        SELECT MAX(urutan)
        FROM perkara_jadwal_sidang
        WHERE perkara_id = '#perkara_id#'
    ) = 1 THEN
        "<br>Bahwa, #0690# telah memeriksa identitas #7036# dan #7037# yang ternyata sesuai dengan yang tertera dalam surat #0053# sebagai keterangan para pihak;"
    ELSE
        "<br>Bahwa, #0690# telah memeriksa identitas #7036# yang ternyata sesuai dengan yang tertera dalam surat #0053#;"
END AS data
FROM perkara
LEFT JOIN perkara_efiling_id ON perkara.perkara_id = perkara_efiling_id.perkara_id
LEFT JOIN perkara_jadwal_sidang ON perkara.perkara_id = perkara_jadwal_sidang.perkara_id
LEFT JOIN perkara_pihak1 ON perkara.perkara_id = perkara_pihak1.perkara_id
LEFT JOIN perkara_mediasi ON perkara.perkara_id = perkara_mediasi.perkara_id
JOIN perkara_jadwal_sidang AS sidang ON sidang.perkara_id = perkara.perkara_id
LEFT JOIN (
        SELECT
            perkara.perkara_id AS perkara_id,
            perkara_jadwal_sidang.urutan AS urutan,
            perkara_jadwal_sidang.dihadiri_oleh
        FROM
            perkara
            JOIN perkara_jadwal_sidang ON (
                perkara_jadwal_sidang.perkara_id = perkara.perkara_id
            )
    ) AS jadwalsidang ON (
        jadwalsidang.perkara_id = perkara.perkara_id
        AND jadwalsidang.urutan = sidang.urutan - 1
    )
    LEFT JOIN perkara_penetapan_hari_sidang AS phs ON (
        phs.perkara_id = perkara.perkara_id
        AND phs.jadwalsidang_id = sidang.id
    )
WHERE perkara.perkara_id = '#perkara_id#';

